# End-to-end journeys (Student, Proctor, Admin). Needs: pip install playwright && playwright install chromium
# Serve the project first: python3 -m http.server 8765
import asyncio, re
from playwright.async_api import async_playwright, expect
B='http://localhost:8765/'
def log(*a): print(' ', *a, flush=True)
async def newpage(b, w=1440, h=900):
  ctx=await b.new_context(viewport={'width':w,'height':h}); await ctx.route(re.compile(r'fonts\.'), lambda r: r.abort())
  pg=await ctx.new_page(); errs=[]; pg.on('pageerror', lambda e: errs.append(str(e))); return ctx, pg, errs
async def login(pg, role):
  await pg.goto(B+'login.html'); await pg.click(f'[data-role={role}]'); await pg.click('button[type=submit]')
async def student(b):
  print('STUDENT'); ctx,pg,errs=await newpage(b)
  await login(pg,'student'); await pg.wait_for_url('**/student/dashboard.html'); log('dashboard ok')
  await pg.click('text=Start with system check'); await pg.wait_for_url('**/system-check.html?id=exam_001')
  await pg.click('[data-action=simulate]'); await pg.wait_for_timeout(2500)
  await pg.click('#go'); await pg.wait_for_url('**/instructions.html?id=exam_001'); log('system check ok')
  await pg.click('#start'); await pg.wait_for_timeout(300); log('blocked without consent:', 'instructions' in pg.url)
  for k in ['c1','c2','c3']: await pg.check('#f-'+k)
  await pg.click('#cap'); await pg.wait_for_timeout(1200); await pg.click('#start'); await pg.wait_for_url('**/take-exam.html?id=exam_001'); await pg.wait_for_selector('#q-card .q-prompt')
  log('exam started, timer:', await pg.inner_text('#clock'))
  await pg.click('.q-option:has-text("String")'); await pg.wait_for_timeout(1200); log('save state:', await pg.inner_text('#save'))
  await pg.click('#next'); await pg.click('.q-option >> nth=0'); await pg.click('#review'); await pg.wait_for_timeout(300)
  await pg.click('#next'); await pg.click('.q-option:has-text("ArrayList")'); await pg.click('.q-option:has-text("LinkedList")')
  await pg.click('.pal-btn[data-q="5"]'); await pg.fill('#ans-num','8'); await pg.wait_for_timeout(1200)
  states=await pg.eval_on_selector_all('#pal-groups .pal-btn','e=>e.map(x=>x.dataset.state||"none")'); log('palette:', states[:7])
  await pg.click('#submit-top'); await pg.wait_for_selector('[role=dialog]')
  log('submit disabled before confirm:', await pg.is_disabled('[data-primary]'))
  await pg.check('#confirm-submit'); await pg.click('[data-primary]'); await pg.wait_for_url('**/submitted.html?attempt=*')
  log('submitted:', (await pg.inner_text('h1')))
  await pg.click('text=View my result'); await pg.wait_for_url('**/result-detail.html?id=*'); await pg.wait_for_selector('.ring')
  log('result:', await pg.inner_text('.ring strong'), '| review items:', await pg.locator('.question-review').count())
  log('errors:', errs); await ctx.close()
async def proctor(b):
  print('PROCTOR'); ctx,pg,errs=await newpage(b)
  await login(pg,'proctor'); await pg.wait_for_url('**/proctor/dashboard.html'); log('dashboard ok')
  await pg.click('[data-avail=busy]'); await pg.wait_for_timeout(800)
  await pg.goto(B+'proctor/live-sessions.html'); await pg.click('text=Open console >> nth=0'); await pg.wait_for_url('**/console.html?session=*'); await pg.wait_for_selector('.cand-card')
  n0=await pg.locator('#stream .event').count(); await pg.wait_for_timeout(9000); n1=await pg.locator('#stream .event').count(); log('live events streamed:', n0, '->', n1)
  await pg.click('[data-filter=attention]'); log('needs-attention cards:', await pg.locator('.cand-card').count())
  await pg.fill('#cq','varun'); await pg.wait_for_timeout(400); log('search varun:', await pg.locator('.cand-card').count()); await pg.fill('#cq','')
  await pg.click('.cand-card >> nth=0'); await pg.wait_for_url('**/candidate.html?*'); await pg.wait_for_selector('[data-action=flag]')
  name=await pg.inner_text('h1'); log('candidate:', name)
  await pg.click('[data-action=flag]'); await pg.select_option('.overlay [name=type]','tab_switch'); await pg.select_option('.overlay [name=severity]','high'); await pg.fill('.overlay [name=description]','Left the tab three times after a warning.'); await pg.click('[data-primary]'); await pg.wait_for_timeout(1500)
  await pg.fill('#f-note','Candidate acknowledged the warning.'); await pg.click('#notef [type=submit]'); await pg.wait_for_timeout(1500)
  log('timeline has flag+note:', await pg.locator('#tl li:has-text("Incident flagged")').count()>0, await pg.locator('#tl li:has-text("Note")').count()>0)
  await pg.click('[data-action=warn]'); await pg.click('[data-primary]'); await pg.wait_for_timeout(1200); log('warnings now in status:', 'Warnings sent' in await pg.inner_text('#status'))
  await pg.click('text=Back to console'); await pg.wait_for_selector('[data-action=end]'); await pg.click('[data-action=end]'); await pg.fill('.overlay [name=notes]','Session closed early for test.'); await pg.click('[data-primary]')
  await pg.wait_for_url('**/session-summary.html?*'); await pg.wait_for_selector('h1'); log('summary:', await pg.inner_text('h1'), '| incidents listed:', await pg.locator('aside .list-item').count())
  await pg.goto(B+'proctor/incidents.html'); await pg.wait_for_selector('[data-review]'); await pg.click('[data-review] >> nth=0'); await pg.select_option('.drawer [name=status]','resolved'); await pg.click('.drawer [data-primary]'); await pg.wait_for_timeout(1000); log('incident resolved ok')
  log('errors:', errs); await ctx.close()
async def admin(b):
  print('ADMIN'); ctx,pg,errs=await newpage(b)
  await login(pg,'admin'); await pg.wait_for_url('**/verify-otp.html')
  for i,d in enumerate('123456'): await pg.locator('.otp input').nth(i).fill(d)
  await pg.wait_for_url('**/admin/dashboard.html'); await pg.wait_for_selector('.metric'); log('OTP -> dashboard ok')
  await pg.click('.page-actions >> text=Create exam'); await pg.wait_for_url('**/exam-wizard.html')
  await pg.click('[data-next]'); log('step1 validation blocks:', await pg.inner_text('#step-t'))
  await pg.fill('#f-title','Spring Boot Microservices'); await pg.fill('#f-code','sb-410'); await pg.click('[data-next]')
  await pg.fill('#f-startAt','2026-11-20T10:00'); await pg.fill('#f-endAt','2026-11-20T09:00'); await pg.click('[data-next]'); await pg.wait_for_timeout(200)
  log('end<start error:', (await pg.inner_text('#f-endAt-err')).strip())
  await pg.fill('#f-endAt','2026-11-20T14:00'); await pg.click('[data-next]')
  for q in ['q_001','q_003','q_008','q_012']: await pg.check(f'#qpick input[value={q}]')
  log('selected:', await pg.inner_text('.card-flat .tag'))
  await pg.click('[data-save]'); await pg.wait_for_timeout(1000); log('draft saved, url has id:', 'id=' in pg.url)
  await pg.click('[data-next]'); await pg.click('[data-group="Campus Drive 2026, Batch A"]'); await pg.wait_for_timeout(300); log('candidates:', await pg.inner_text('.metric-value'))
  await pg.click('[data-next]'); await pg.check('[name=proctorIds][value=prc_004]'); await pg.click('[data-next]'); await pg.click('[data-next]'); await pg.click('[data-next]')
  log('review step:', await pg.inner_text('#step-t'), '| ready:', await pg.locator('.alert[data-tone=ok]').count()==1)
  await pg.click('[data-publish]'); await pg.wait_for_url('**/exam-detail.html?id=*&published=1'); await pg.wait_for_selector('.page-header h1'); log('published:', await pg.inner_text('.page-header h1'), '|', await pg.inner_text('.page-header .chip'))
  await pg.goto(B+'admin/question-editor.html'); await pg.wait_for_selector('#qf'); await pg.fill('#f-prompt','Which annotation marks a Spring REST controller?')
  for i,t in enumerate(['@Service','@RestController','@Entity','@Bean']): await pg.fill(f'#opt-{i}',t)
  await pg.click('[type=submit]'); await pg.wait_for_timeout(300); log('editor blocks w/o correct:', 'question-editor' in pg.url)
  await pg.check('[name=correct][value=b]'); await pg.click('[type=submit]'); await pg.wait_for_url('**/question-bank.html'); log('question saved')
  await pg.goto(B+'admin/students.html?add=1'); await pg.wait_for_selector('#sf'); await pg.fill('#f-name','Test Candidate'); await pg.fill('#f-email','test.candidate@mail.com'); await pg.click('[data-primary]'); await pg.wait_for_timeout(1500)
  await pg.fill('#q','test cand'); await pg.wait_for_timeout(500); log('student added visible:', await pg.locator('.td-primary:has-text("Test Candidate")').count())
  await pg.goto(B+'admin/proctors.html'); await pg.wait_for_selector('.td-primary'); log('proctors rows:', await pg.locator('tbody tr').count())
  await pg.goto(B+'admin/results.html?exam=exam_007'); await pg.wait_for_selector('[data-sel]'); await pg.click('[data-sel] >> nth=0'); await pg.click('[data-sel] >> nth=1'); await pg.click('[data-action=publishSel]'); await pg.wait_for_timeout(1500); log('published results, remaining unpublished checkboxes:', await pg.locator('[data-sel]').count())
  await pg.goto(B+'admin/reports.html'); await pg.wait_for_selector('svg.chart'); log('report charts:', await pg.locator('svg.chart').count())
  await pg.click('[data-theme-toggle]'); await pg.goto(B+'admin/dashboard.html'); log('theme persisted:', await pg.evaluate('document.documentElement.dataset.theme'))
  await pg.goto(B+'student/dashboard.html'); await pg.wait_for_timeout(500); log('admin -> student page redirected to:', pg.url.split('/')[-1])
  log('errors:', errs); await ctx.close()
async def main():
  async with async_playwright() as p:
    b=await p.chromium.launch()
    for f in (student, proctor, admin):
      try: await f(b)
      except Exception as e: print('  FAILED:', str(e)[:400])
    await b.close()
asyncio.run(main())
